keys(k,role) as (values('P1CIR01-D01','diagnostic'),('P1CIR01-L01','learning'),('P1CIR01-L02','learning'),('P1CIR01-L03','learning'),('P1CIR01-R01','retest'),('P1CIR01-R02','retest'),('P1CIR01-M01','mixed'))
insert into private.exam_prep_question_content_meta(content_version_id,content_key,question_id,primary_skill_code,secondary_skill_codes,reserve_role,exposure_state,lifecycle_state,originality_attestation,provenance_note,official_scope_ref,coursebook_mapping_ref,copyright_status,qa_scope_status,qa_math_status,qa_language_status,qa_technical_status,diagnostic_rule_status,question_snapshot_md5)
select cv.id,k.k,q.id,'P1-CIR-01','{}'::text[],k.role,'withheld','draft','Original iClub-authored stem, distractors, answer and explanation; no Cambridge/coursebook wording copied.','Authored from canonical degree/radian conversion using independent values.','Cambridge 9709 2026-2027 v4; P1 1.4 Circular measure','Complete Pure Mathematics 1, Ch4 Circular measure pp.74-81 (mapping only)','pending','pending','pending','pending','pending',case when k.role='diagnostic' then 'pending' else 'not_applicable' end,
md5(concat_ws(chr(31),q.id::text,q.subject_id::text,coalesce(q.topic,''),coalesce(q.subtopic,''),coalesce(q.difficulty,''),coalesce(q.qtype,''),coalesce(q.question_text,''),coalesce(q.options_text,''),coalesce(q.correct_answer,''),coalesce(q.explanation,''),coalesce(q.image_url,''),coalesce(q.is_active::text,''),coalesce(q.question_text_ru,''),coalesce(q.question_text_uz,''),coalesce(q.question_text_en,''),coalesce(q.options_text_ru,''),coalesce(q.options_text_uz,''),coalesce(q.options_text_en,''),coalesce(q.explanation_ru,''),coalesce(q.explanation_uz,''),coalesce(q.explanation_en,''),coalesce(q.book_ref,''),coalesce(q.time_limit_sec::text,''),coalesce(q.quality_flag,''),coalesce(q.quality_status,''))) from cv cross join keys k join public.questions q on q.book_ref='ExamPrep:P1:p1_e2_coordinate_circular_trig_v1:'||k.k
on conflict(content_version_id,content_key) do nothing;
do $$ declare v_id bigint; begin select id into v_id from private.exam_prep_content_versions where content_version='p1_e2_coordinate_circular_trig_v1'; if (select count(*) from private.exam_prep_question_content_meta where content_version_id=v_id and primary_skill_code='P1-CIR-01')<>7 then raise exception 'P1-02 CIR-01 expected 7 question objects'; end if; end $$;
